package store.cadera.cdrjobs.listener;
import net.kyori.adventure.text.Component;import org.bukkit.*;import org.bukkit.block.*;import org.bukkit.entity.Player;import org.bukkit.event.*;import org.bukkit.event.block.*;import org.bukkit.event.entity.EntityExplodeEvent;import org.bukkit.potion.*;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.api.ProfessionActionType;import store.cadera.cdrjobs.api.event.ProfessionActionEvent;import store.cadera.cdrjobs.data.Database;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;import java.util.*;
public final class MinerListener implements Listener{private final CdrJobsPlugin plugin;private final Database db;private final ProgressionService progression;private final SkillService skills;private final LevelService levels;private final MinerTrialService trials;private final MinerAbilityService abilities;private Map<Material,Integer>xp;private final Map<UUID,Streak>streaks=new HashMap<>();public MinerListener(CdrJobsPlugin p,Database d,ProgressionService pr,SkillService s,LevelService l,MinerTrialService t,MinerAbilityService a){plugin=p;db=d;progression=pr;skills=s;levels=l;trials=t;abilities=a;refreshXpMap();}public void refreshXpMap(){xp=plugin.loadMinerXp();}
@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void place(BlockPlaceEvent e){if(plugin.getConfig().getBoolean("miner.enabled",true)&&placed()&&xp.containsKey(e.getBlockPlaced().getType()))db.markPlacedOre(e.getBlockPlaced().getLocation());}
@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void extend(BlockPistonExtendEvent e){move(e.getBlocks(),e.getDirection());}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void retract(BlockPistonRetractEvent e){move(e.getBlocks(),e.getDirection().getOppositeFace());}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void explode(BlockExplodeEvent e){cleanup(e.blockList());}@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void explode2(EntityExplodeEvent e){cleanup(e.blockList());}
@EventHandler(priority=EventPriority.MONITOR,ignoreCancelled=true)public void breakOre(BlockBreakEvent e){if(!plugin.getConfig().getBoolean("miner.enabled",true))return;Block b=e.getBlock();Integer base=xp.get(b.getType());if(base==null)return;if(placed()&&db.consumePlacedOre(b.getLocation()))return;Player p=e.getPlayer();trials.onNaturalOreMined(p,b);long tuned=Math.max(1,Math.round(base*Math.max(.01,plugin.getConfig().getDouble("miner.xp-multiplier",1))));long amount=abilities.applyXpBoost(p,skills.applyMinerXpModifiers(p,tuned));plugin.getServer().getPluginManager().callEvent(new ProfessionActionEvent(p,JobType.MINER,ProfessionActionType.MINE_ORE,1));JobProgress pr=progression.addXp(p,JobType.MINER,amount);streak(p);if(plugin.getConfig().getBoolean("settings.actionbar-xp",true)){long req=levels.xpRequiredForNextLevel(pr.level());p.sendActionBar(Component.text(pr.level()>=levels.maxLevel()?"✦ Runebound Delver Lv."+levels.maxLevel()+" • MAX":"✦ Runebound +"+amount+" XP • Lv."+pr.level()+" • "+pr.xp()+"/"+req));}}
private boolean placed(){return plugin.getConfig().getBoolean("anti-exploit.placed-ore-tracking",true);}private void cleanup(List<Block>bs){if(!placed()||!plugin.getConfig().getBoolean("anti-exploit.cleanup-exploded-ores",true))return;for(Block b:bs)if(xp.containsKey(b.getType()))db.consumePlacedOre(b.getLocation());}private void move(List<Block>bs,BlockFace dir){if(!placed()||!plugin.getConfig().getBoolean("anti-exploit.piston-move-tracking",true))return;List<Location>tos=new ArrayList<>();for(Block b:bs)if(xp.containsKey(b.getType())&&db.isPlacedOre(b.getLocation())){db.consumePlacedOre(b.getLocation());tos.add(b.getRelative(dir).getLocation());}tos.forEach(db::markPlacedOre);}private void streak(Player p){int r=db.getSkillRank(p.getUniqueId(),MinerSkill.ECHO_OF_DEPTH);if(r<=0)return;long now=System.currentTimeMillis();Streak old=streaks.get(p.getUniqueId());int c=old==null||now-old.last>60000?1:old.count+1;if(c>=Math.max(10,25-(r-1)*5)){p.addPotionEffect(new PotionEffect(PotionEffectType.HASTE,160,r>=3?1:0,true,false,true));c=0;}streaks.put(p.getUniqueId(),new Streak(c,now));}private record Streak(int count,long last){}
}
